<script>
(function(){var input=document.getElementById('archivos'),zone=document.getElementById('drop-zone'),summary=document.getElementById('file-summary'),button=document.getElementById('upload-button'),form=document.getElementById('biopsy-upload');function show(){var count=input.files?input.files.length:0;summary.textContent=count?count+' archivo(s) seleccionado(s)':'PDF, JPG, PNG, DOC o DOCX · máximo 15 MB por archivo';}input.addEventListener('change',show);['dragenter','dragover'].forEach(function(name){zone.addEventListener(name,function(e){e.preventDefault();zone.classList.add('is-over');});});['dragleave','drop'].forEach(function(name){zone.addEventListener(name,function(e){e.preventDefault();zone.classList.remove('is-over');if(name==='drop'&&e.dataTransfer&&e.dataTransfer.files){input.files=e.dataTransfer.files;show();}});});form.addEventListener('submit',function(){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i> Procesando archivos...';});})();
</script>
